```java
// Features from several starters working together (Spring Boot 3.2, Java 17)
@RestController
@RequestMapping("/api/users")
class UserController {
    private final UserRepository repo;                 // starter-data-jpa
    UserController(UserRepository repo) { this.repo = repo; }

    @PostMapping
    @PreAuthorize("hasRole('ADMIN')")                 // starter-security
    User create(@Valid @RequestBody UserRequest req) { // starter-validation
        return repo.save(new User(req.name(), req.email()));
    }
}
```

