// Booting the whole context just to test a calculation = slow (3-5s each)
@SpringBootTest
class OrderServiceTest {
    @Autowired OrderService service;
    @MockBean OrderRepository repository;

    @Test
    void total() {
        when(repository.findById(1L)).thenReturn(Optional.of(new Order(1L, "Laptop", 1000)));
        assertThat(service.calculateTotal(1L)).isEqualTo(1000);
    }
}
