```java
// No Spring context: fast, isolated unit test
@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock OrderRepository repository;
    @InjectMocks OrderService service;

    @Test
    void total() {
        when(repository.findById(1L)).thenReturn(Optional.of(new Order(1L, "Laptop", 1000)));
        assertThat(service.calculateTotal(1L)).isEqualTo(1000); // AssertJ
        verify(repository).findById(1L);                        // Mockito
    }
}

